-- SOLO LECTURA. Todos los controles deben dar errores=0. El runner rechaza cualquier otro resultado.
SELECT 'destino' AS control, (CASE WHEN DATABASE() REGEXP '^c3c1_lab_[a-f0-9]{32}$' THEN 0 ELSE 1 END) AS errores;
SELECT 'version' AS control, (CASE WHEN (VERSION() LIKE '11.8.%' AND VERSION() LIKE '%MariaDB%') OR (VERSION() LIKE '8.0.%' AND CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(VERSION(),'-',1),'.',-1) AS UNSIGNED) >= 16) THEN 0 ELSE 1 END) AS errores;
SELECT 'fk_habilitadas' AS control, (CASE WHEN @@foreign_key_checks = 1 THEN 0 ELSE 1 END) AS errores;
SELECT 'padres_innodb' AS control, (4 - (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('empresas','cont_entidades','usuarios','auditoria') AND ENGINE='InnoDB')) AS errores;
SELECT 'claves_padres' AS control, (4 - (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND ((TABLE_NAME IN ('empresas','usuarios') AND COLUMN_NAME='id') OR (TABLE_NAME='cont_entidades' AND COLUMN_NAME IN ('empresa_id','id'))) AND DATA_TYPE='int' AND COLUMN_TYPE NOT LIKE '%unsigned%' AND IS_NULLABLE='NO')) AS errores;
SELECT 'columnas_servicio' AS control, (6 - (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND ((TABLE_NAME='cont_entidades' AND COLUMN_NAME='activa' AND DATA_TYPE='tinyint') OR (TABLE_NAME='auditoria' AND COLUMN_NAME='empresa_id' AND DATA_TYPE='int' AND COLUMN_TYPE NOT LIKE '%unsigned%') OR (TABLE_NAME='auditoria' AND COLUMN_NAME IN ('usuario','accion','modulo') AND DATA_TYPE='varchar' AND CHARACTER_MAXIMUM_LENGTH>=100*(COLUMN_NAME='usuario')+80*(COLUMN_NAME='accion')+40*(COLUMN_NAME='modulo')) OR (TABLE_NAME='auditoria' AND COLUMN_NAME='detalle' AND DATA_TYPE IN ('text','mediumtext','longtext'))))) AS errores;
SELECT 'indices_padres' AS control, (3 - (SELECT COUNT(*) FROM (SELECT TABLE_NAME, INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS cols FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND NON_UNIQUE=0 AND TABLE_NAME IN ('empresas','usuarios','cont_entidades') GROUP BY TABLE_NAME,INDEX_NAME) x WHERE (TABLE_NAME IN ('empresas','usuarios') AND INDEX_NAME='PRIMARY' AND cols='id') OR (TABLE_NAME='cont_entidades' AND cols='empresa_id,id'))) AS errores;
SELECT 'calendario_ausente' AS control, ((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('cont_ejercicios','cont_periodos'))) AS errores;
SELECT 'auditoria_automaticos' AS control, (2 - (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='auditoria' AND ((COLUMN_NAME='id' AND DATA_TYPE IN ('int','bigint') AND EXTRA LIKE '%auto_increment%') OR (COLUMN_NAME='creado_en' AND DATA_TYPE IN ('datetime','timestamp') AND UPPER(COALESCE(COLUMN_DEFAULT,'')) LIKE 'CURRENT_TIMESTAMP%')))) AS errores;
SELECT 'auditoria_sin_obligatorias_extra' AS control, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='auditoria' AND COLUMN_NAME NOT IN ('empresa_id','usuario','accion','modulo','detalle') AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA NOT LIKE '%auto_increment%' AND EXTRA NOT LIKE '%GENERATED%') AS errores;
SELECT 'entidad_empresa_fk' AS control, (CASE WHEN EXISTS (SELECT 1 FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='cont_entidades' AND COLUMN_NAME='empresa_id' AND REFERENCED_TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME='empresas' AND REFERENCED_COLUMN_NAME='id') THEN 0 ELSE 1 END) AS errores;
